-- "nine" sample dataset for SQLite (file engine: no container). Fake data
-- only, generated by recursive CTEs. Driver tests apply it to a temporary
-- database file, e.g.  sqlite3 /tmp/nine.db < dev/seed/sqlite/nine.sql

PRAGMA foreign_keys = ON;
BEGIN;

CREATE TABLE customers (
  id          INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  email       TEXT NOT NULL UNIQUE,
  country     TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE products (
  id        INTEGER PRIMARY KEY,
  sku       TEXT NOT NULL UNIQUE,
  name      TEXT NOT NULL,
  category  TEXT NOT NULL,
  price     NUMERIC NOT NULL
);

CREATE TABLE orders (
  id           INTEGER PRIMARY KEY,
  customer_id  INTEGER NOT NULL REFERENCES customers (id),
  product_id   INTEGER NOT NULL REFERENCES products (id),
  quantity     INTEGER NOT NULL,
  status       TEXT NOT NULL,
  ordered_at   TEXT NOT NULL
);
CREATE INDEX orders_customer_idx ON orders (customer_id);

WITH RECURSIVE s(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM s WHERE i < 1000)
INSERT INTO customers
SELECT i, 'Customer ' || i, 'customer' || i || '@example.com',
       substr('FRDEUSJPBRINNGCAAU', 1 + 2 * (i % 9), 2),
       strftime('%Y-%m-%dT%H:%M:%SZ', '2024-01-01 00:00:00', '+' || (i * 37) || ' minutes')
FROM s;

WITH RECURSIVE s(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM s WHERE i < 100)
INSERT INTO products
SELECT i, 'SKU-' || printf('%05d', i), 'Product ' || i,
       CASE i % 5 WHEN 0 THEN 'books' WHEN 1 THEN 'games' WHEN 2 THEN 'tools' WHEN 3 THEN 'garden' ELSE 'music' END,
       round(1 + (i * 7919) % 50000 / 100.0, 2)
FROM s;

WITH RECURSIVE s(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM s WHERE i < 10000)
INSERT INTO orders
SELECT i, 1 + (i * 31) % 1000, 1 + (i * 17) % 100, 1 + i % 9,
       CASE i % 5 WHEN 0 THEN 'new' WHEN 1 THEN 'paid' WHEN 2 THEN 'shipped' WHEN 3 THEN 'delivered' ELSE 'cancelled' END,
       strftime('%Y-%m-%dT%H:%M:%SZ', '2025-01-01 00:00:00', '+' || (i * 13) || ' minutes')
FROM s;

-- SQLite has five storage classes; the declared types below exercise type
-- affinity as other tools (and DBeaver) display it. Row 3 is all NULLs.
CREATE TABLE all_types (
  id           INTEGER PRIMARY KEY,
  c_integer    INTEGER,
  c_bigint     BIGINT,
  c_real       REAL,
  c_double     DOUBLE,
  c_numeric    NUMERIC,
  c_decimal    DECIMAL(20,6),
  c_boolean    BOOLEAN,
  c_text       TEXT,
  c_varchar    VARCHAR(64),
  c_blob       BLOB,
  c_date       DATE,
  c_datetime   DATETIME,
  c_json       JSON,
  c_untyped
);

INSERT INTO all_types VALUES
  (1, 4242, 424242424242, 3.14, 2.718281828459045, 12345.678901, 12345.678901, 1,
   'text value with unicode: café, 日本, 🙂', 'varchar value', X'DEADBEEF', '2026-11-14',
   '2026-11-14 13:37:00', '{"a": 1, "b": [true, null]}', 'any'),
  (2, -9223372036854775808, 9223372036854775807, -1.5, -1e300, -99999999999999.999999, 0, 0,
   '', '', X'', '0001-01-01', '1970-01-01 00:00:00', '[]', 42),
  (3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- 1 000 000 rows, generated in the engine.
CREATE TABLE big_events (
  id          INTEGER PRIMARY KEY,
  event_time  TEXT NOT NULL,
  kind        TEXT NOT NULL,
  value       REAL NOT NULL,
  payload     TEXT
);

WITH RECURSIVE s(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM s WHERE i < 1000000)
INSERT INTO big_events
SELECT i, strftime('%Y-%m-%dT%H:%M:%SZ', '2026-01-01 00:00:00', '+' || i || ' seconds'),
       CASE i % 4 WHEN 0 THEN 'click' WHEN 1 THEN 'view' WHEN 2 THEN 'buy' ELSE 'error' END,
       (i % 1000) / 10.0,
       CASE WHEN i % 10 = 0 THEN NULL ELSE 'event ' || i END
FROM s;

CREATE VIEW customer_order_totals AS
SELECT c.id, c.name, count(o.id) AS order_count, coalesce(sum(o.quantity * p.price), 0) AS total
FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
LEFT JOIN products p ON p.id = o.product_id
GROUP BY c.id, c.name;

CREATE TABLE nine_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO nine_meta VALUES ('seed_version', '1'), ('big_events_rows', '1000000');

COMMIT;
